    @if (filled($name))
        <input type="hidden" name="{{ $name }}" value="{{ $resolvedValue }}" data-date-picker-hidden-input />
    @else
        <input type="hidden" value="{{ $resolvedValue }}" data-date-picker-hidden-input />
