        data-date-picker-panel
        hidden
        aria-hidden="true"
        tabindex="-1"
        aria-label="{{ $range ? __('stencil-ui::messages.date_picker_range_placeholder') : __('stencil-ui::messages.date_picker_placeholder') }}"
    >
        <div class="grid sm:grid-cols-[auto_1fr]">
            @if ($presetMeta !== [])
                <div class="hidden border-e border-zinc-200 p-2 sm:block dark:border-zinc-800" data-date-picker-presets>
