                    :force-open-to="$forceOpenTo"
                    :size="$size ?? 'default'"
                    :min-range="$minRange"
                    :max-range="$maxRange"
                />
            </div>
        </div>

        @if ($withConfirmation)
            <div class="mt-2 flex justify-end gap-2 border-t border-zinc-200 pt-2 dark:border-zinc-800">
