                    {{ __('stencil-ui::messages.date_picker_cancel') }}
                </x-ui::button>
                <x-ui::button type="button" variant="primary" data-date-picker-confirm>
                    {{ $range ? __('stencil-ui::messages.date_picker_select_range') : __('stencil-ui::messages.date_picker_select_date') }}
                </x-ui::button>
            </div>
        @endif
    </div>
</div>

